insert into public.products (slug,category,brand,collection,name,material,style,color,price,description,features,image_path,sort_order,is_available) values ('darumi-dta8av','interior','Darumi','Darumi Авант','Darumi Avant','ламіновані','сучасний','білий мат','Ціна за запитом','Darumi Avant — міжкімнатні двері фабрики Дарумі (Корюківка). Основні параметри: покриття ELBEGY ® (Японія), полотно 40 мм, розміри 60, 70, 80, 90 х 200. Доступні заводські декори та варіанти скла; актуальну комплектацію й ціну уточнюйте у менеджера.','["Фабрика Darumi","Колекція Darumi Авант","Варіанти декорів і скла"]'::jsonb,'https://darumi.in.ua/images/dveri/biliy-mat/avant-sklo-bronza/dveri-biliy-mat-avant-sklo-bronza.jpg',99999,false) on conflict (slug) do update set collection=excluded.collection,name=excluded.name,material=excluded.material,style=excluded.style,color=excluded.color,description=excluded.description,image_path=excluded.image_path,updated_at=now();
